import {
  LIMA_CPUS,
  LIMA_DISK_GIB,
  LIMA_MEMORY,
  LIMA_TEMPLATE,
} from './constants.js';

/**
 * 生成 `kepcup` 实例的 Lima YAML（写入应用数据目录后交给 `limactl create`）。
 *
 * 挂载策略：策略里的工作区、应用缓存、工具链、技能目录都在用户 home 下
 * （packages/core/src/sandbox/policy.ts），而 `limactl exec` 不支持逐条绑定，
 * 所以创建时把 `~` 以同径、可写方式挂进 VM，由 VM 内的 srt 继续执行逐命令
 * 的读写白名单。`/tmp` 不在策略内（srt 会把 TMPDIR 重定向到沙箱私有位置），
 * 无需额外挂载。containerd 关闭：增强沙箱不需要容器运行时，避免额外的镜像
 * 下载与攻击面。
 */
export function buildLimaInstanceYaml(): string {
  return [
    '# Generated by KepCup — 增强沙箱（Lima）实例配置，请勿手工编辑。',
    `base:`,
    `  - ${LIMA_TEMPLATE}`,
    `cpus: ${LIMA_CPUS}`,
    `memory: "${LIMA_MEMORY}"`,
    // Lima parses a bare number as bytes (and refuses to shrink the 3GiB base
    // image); the template's disk field needs an explicit unit.
    `disk: "${LIMA_DISK_GIB}GiB"`,
    'containerd:',
    '  system: false',
    '  user: false',
    'mounts:',
    '  - location: "~"',
    '    writable: true',
    '',
  ].join('\n');
}
